class Solution {
    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxCoins($nums) {
        $n = count($nums);
        // Add 1 to both ends to simplify calculations
        $points = array_merge([1], $nums, [1]);
        // DP array: dp[left][right] = max coins obtained 
        // by bursting all balloons between left and right (exclusive)
        $dp = array_fill(0, $n + 2, array_fill(0, $n + 2, 0));

        // we only consider intervals with length >= 2 (left + 1 < right)
        for ($length = 2; $length <= $n + 1; $length++) {
            for ($left = 0; $left + $length <= $n + 1; $left++) {
                $right = $left + $length;
                for ($k = $left + 1; $k < $right; $k++) {
                    // last burst balloon k in (left, right)
                    $coins = $points[$left] * $points[$k] * $points[$right];
                    $coins += $dp[$left][$k] + $dp[$k][$right];
                    $dp[$left][$right] = max($dp[$left][$right], $coins);
                }
            }
        }
        return $dp[0][$n + 1];
    }
}

